describe('Active Filter Tags Display', () => {
  beforeEach(() => {
    cy.visit('/search');
    cy.get('[data-testid="search-container"]').should('be.visible');
  });

  it('should display tag for each active filter above results', () => {
    // Apply first filter
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="filter-option-electronics"]').click();

    // Apply second filter
    cy.get('[data-testid="filter-price"]').click();
    cy.get('[data-testid="filter-option-under-100"]').click();

    // Apply third filter
    cy.get('[data-testid="filter-brand"]').click();
    cy.get('[data-testid="filter-option-samsung"]').click();

    // Verify filter tags container exists
    cy.get('[data-testid="active-filters-container"]').should('be.visible');

    // Verify each filter tag is displayed
    cy.get('[data-testid="filter-tag-category"]').should('contain', 'Category: Electronics');
    cy.get('[data-testid="filter-tag-price"]').should('contain', 'Price: Under $100');
    cy.get('[data-testid="filter-tag-brand"]').should('contain', 'Brand: Samsung');

    // Verify tags appear above results
    cy.get('[data-testid="active-filters-container"]').then(($filterContainer) => {
      cy.get('[data-testid="search-results"]').then(($results) => {
        expect($filterContainer.offset().top).to.be.lessThan($results.offset().top);
      });
    });

    // Verify correct number of tags
    cy.get('[data-testid="filter-tag"]').should('have.length', 3);
  });

  it('should remove filter tag when filter is cleared and update results', () => {
    // Apply multiple filters
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="filter-option-electronics"]').click();

    cy.get('[data-testid="filter-price"]').click();
    cy.get('[data-testid="filter-option-under-100"]').click();

    // Verify both tags are displayed
    cy.get('[data-testid="filter-tag"]').should('have.length', 2);

    // Remove one filter by clicking the X on the tag
    cy.get('[data-testid="filter-tag-category"] [data-testid="remove-filter"]').click();

    // Verify only one tag remains
    cy.get('[data-testid="filter-tag"]').should('have.length', 1);
    cy.get('[data-testid="filter-tag-price"]').should('be.visible');
    cy.get('[data-testid="filter-tag-category"]').should('not.exist');

    // Verify results are updated
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);
  });

  it('should display no filter tags when no filters are applied', () => {
    // Verify no filter tags are shown initially
    cy.get('[data-testid="active-filters-container"]').should('not.exist');
    cy.get('[data-testid="filter-tag"]').should('not.exist');

    // Verify results are displayed without filters
    cy.get('[data-testid="search-results"]').should('be.visible');
  });

  it('should handle clearing all filters at once', () => {
    // Apply multiple filters
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="filter-option-electronics"]').click();

    cy.get('[data-testid="filter-price"]').click();
    cy.get('[data-testid="filter-option-under-100"]').click();

    cy.get('[data-testid="filter-tag"]').should('have.length', 2);

    // Click clear all filters button
    cy.get('[data-testid="clear-all-filters"]').click();

    // Verify all tags are removed
    cy.get('[data-testid="filter-tag"]').should('not.exist');
    cy.get('[data-testid="active-filters-container"]').should('not.exist');

    // Verify results are reset
    cy.get('[data-testid="search-results"]').should('be.visible');
  });

  it('should display filter tags with special characters and long names correctly', () => {
    // Apply filter with special characters
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="filter-option-home-garden"]').click();

    // Apply filter with long name
    cy.get('[data-testid="filter-brand"]').click();
    cy.get('[data-testid="filter-option-very-long-brand-name"]').click();

    // Verify tags are displayed correctly
    cy.get('[data-testid="filter-tag-category"]').should('contain', 'Home & Garden');
    cy.get('[data-testid="filter-tag-brand"]').should('be.visible');

    // Verify tags don't overflow or break layout
    cy.get('[data-testid="active-filters-container"]').should('have.css', 'overflow', 'visible');
    cy.get('[data-testid="filter-tag"]').each(($tag) => {
      cy.wrap($tag).should('be.visible');
    });
  });
});
